def reverse_items(items):
    stack = list(items)
    result = []
    while stack:
        result.append(stack.pop())
    return result

def bucket_put(bucket, key, value):
    for index, (stored_key, _) in enumerate(bucket):
        if stored_key == key:
            bucket[index] = (key, value)
            return
    bucket.append((key, value))

def recursive_sum(values):
    if not values:
        return 0
    return values[0] + recursive_sum(values[1:])

def binary_find(values, target):
    low, high = 0, len(values) - 1
    while low <= high:
        mid = (low + high) // 2
        if values[mid] == target:
            return mid
        if values[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1

def move_count(n):
    if n == 0:
        return 0
    return 2 * move_count(n - 1) + 1

from collections import deque
def reachable(graph, start):
    queue, seen, order = deque([start]), {start}, []
    while queue:
        node = queue.popleft()
        order.append(node)
        for neighbor in graph[node]:
            if neighbor not in seen:
                seen.add(neighbor)
                queue.append(neighbor)
    return order

def fib(n):
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

